package android.app; import java.util.*;
public class NotificationManager { public static final int IMPORTANCE_NONE=0, IMPORTANCE_LOW=2, IMPORTANCE_HIGH=4; public boolean enabled=true; public boolean refuseChannelCreation=false; private final Map<String,NotificationChannel> channels=new HashMap<>(); public final Map<Integer,Notification> notifications=new HashMap<>(); public boolean areNotificationsEnabled(){return enabled;} public NotificationChannel getNotificationChannel(String id){return channels.get(id);} public void createNotificationChannel(NotificationChannel c){if(!refuseChannelCreation)channels.put(c.getId(),c);} public void notify(int id,Notification n){notifications.put(id,n);} public void cancel(int id){notifications.remove(id);} public void setChannel(NotificationChannel c){channels.put(c.getId(),c);} public void clearChannels(){channels.clear();} }
